// A definition is reused; each mount owns a separate instance and setup state.
export function mountView(definition, onError) {
  const instance = { isUnmounted: false, onError };
  const render = definition.setup(instance);
  return {
    unmount() { instance.isUnmounted = true; },
    read() { const view = render(); return view ? view() : null; },
  };
}
